SELECT p.PIPELINE_ID AS row_id, p.ACTIVE_FLAG AS active_flag, 'Y' AS well_formed, p.CALENDAR_ID AS calendar_id, p.PIPELINE_CODE AS pipeline_code, p.PIPELINE_NAME AS pipeline_name, p.DESCRIPTION AS description, p.REFRESH_TYPE AS refresh_type, p.STEWARDABLE_FLAG AS stewardable_flag, p.RUN_SCHEDULE AS run_schedule, p.SCHEDULE_TIMEZONE AS schedule_timezone, p.SCHEDULE_START_DATE AS schedule_start_date, p.CATCHUP AS catchup, p.MAX_CATCHUP_RUNS AS max_catchup_runs, p.OVERLAP_POLICY AS overlap_policy, p.MAX_PARALLEL_TASKS AS max_parallel_tasks, p.PRIORITY AS priority, p.BLOCK_ON_REFRESH_ERROR AS block_on_refresh_error, p.SLA_IN_HOURS AS sla_in_hours, p.PIPELINE_PARAMETERS AS pipeline_parameters, c.CALENDAR_CODE AS calendar_code, p.NON_BUSINESS_DAY AS non_business_day FROM CFG_PIPELINES p LEFT JOIN CFG_CALENDARS c ON c.CALENDAR_ID=p.CALENDAR_ID WHERE p.PROJECT_ID=:project_id ORDER BY 1
